commands:
git fetch origin "+refs/heads/main:refs/remotes/origin/main" || { echo "prflow: could not fetch base branch 'origin/main'" >&2; exit 1; }
BRANCH=$(.prflow/vendor/prflow/scripts/branch-for-issue.py 1645 --title-file .prflow/tmp/devflow-issue-1645-title.txt) || { echo "prflow: branch-for-issue.py failed" >&2; exit 1; }
echo "BRANCH=$BRANCH"
[ -n "$BRANCH" ] || { echo "prflow: empty branch name" >&2; exit 1; }
git checkout -b "$BRANCH" "origin/main"
